using System.Linq;
using UnityEngine;
using UnityEditor;
using LWS.TruckSports;
using LWS.TruckSports.Editor;
namespace LWS.TruckDockDiving.Editor {
public static class DockAuthoring {
 public const string Folder="TruckDockDiving",Scene="Assets/TruckDockDiving/Scenes/TruckDockDiving.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<DockMatch>(Folder);m.setup.count=2;m.feedback.clips=DockAudioAuthoring.Create();var wood=SportsEventAuthoring.Mat(Folder,"Warm dock timber",new Color(.6f,.36f,.15f));var navy=SportsEventAuthoring.Mat(Folder,"Stadium navy",new Color(.025f,.065f,.1f));var ivory=SportsEventAuthoring.Mat(Folder,"Distance ivory",new Color(.96f,.94f,.79f));var teal=SportsEventAuthoring.Mat(Folder,"Pool ceramic",new Color(.08f,.48f,.6f),.65f);var gold=SportsEventAuthoring.Mat(Folder,"Perfect gold",new Color(1,.75f,.16f));var ground=SportsEventAuthoring.Mat(Folder,"Venue lawn",new Color(.11f,.25f,.13f));var deck=SportsEventAuthoring.Contact(Folder,"Grippy dock",.7f,.02f);var contact=SportsEventAuthoring.Contact(Folder,"Pool ground",.35f,.08f);
  m.dock=SportsEventAuthoring.Box("Run-up dock",new Vector3(0,1.1f,-15),new Vector3(7,2.2f,30),wood,deck).GetComponent<Collider>();SportsEventAuthoring.Box("Competitor staging platform",new Vector3(-10,1.1f,-16),new Vector3(12,2.2f,30),navy,deck);foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Venue side ground",new Vector3(side*56,-.4f,50),new Vector3(80,.5f,220),ground,contact);SportsEventAuthoring.Box("Venue front ground",new Vector3(0,-.4f,-55),new Vector3(32,.5f,50),ground,contact);SportsEventAuthoring.Box("Venue far ground",new Vector3(0,-.4f,160),new Vector3(32,.5f,60),ground,contact);SportsEventAuthoring.Box("Pool basin bottom",new Vector3(0,-3.7f,65),new Vector3(22,1,130),teal,contact);
  // NWH water prefab provides the plane geometry; a scoped URP material avoids its legacy water shader.
  var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Prefabs/Water/Water.prefab");var water=new GameObject("NWH water plane · URP pool surface");water.transform.position=new Vector3(0,0,65);water.transform.localScale=new Vector3(2.2f,1,13);water.AddComponent<MeshFilter>().sharedMesh=source.GetComponent<MeshFilter>().sharedMesh;var material=SportsEventAuthoring.Mat(Folder,"Pool water",new Color(.04f,.44f,.66f),.92f);water.AddComponent<MeshRenderer>().sharedMaterial=material;
  var volume=new GameObject("First water contact scoring volume");volume.transform.position=new Vector3(0,-.55f,65);var box=volume.AddComponent<BoxCollider>();box.size=new Vector3(22,1.1f,130);box.isTrigger=true;m.waterVolume=box;
  foreach(int sign in new[]{-1,1}){SportsEventAuthoring.Box("Pool side surround",new Vector3(sign*13.5f,-.25f,65),new Vector3(5,.5f,130),ivory,contact);SportsEventAuthoring.Box("Pool side wall",new Vector3(sign*11.4f,-1.6f,65),new Vector3(.8f,3.2f,130),teal,contact);for(int z=0;z<=130;z+=5){SportsEventAuthoring.Box("Distance mark",new Vector3(sign*11.85f,.025f,z),new Vector3(1.2f,.025f,.12f),navy);var label=SportsEventAuthoring.Label("Distance "+z,DockMatch.Format(DockMatch.Inches(z)),new Vector3(sign*13,.04f,z),.18f,Color.white);label.transform.rotation=Quaternion.Euler(90,0,0);}for(int row=0;row<3;row++)SportsEventAuthoring.Box("Spectator bleacher",new Vector3(sign*(18+row*1.8f),row*.7f,50),new Vector3(1.7f,.6f,100),navy,contact);}
  foreach(float z in new[]{-12f,-8f,-4f})SportsEventAuthoring.Box("Run-up reference",new Vector3(0,2.215f,z),new Vector3(6.8f,.025f,.12f),ivory);SportsEventAuthoring.Box("Launch edge",new Vector3(0,2.22f,-.08f),new Vector3(7,.035f,.16f),gold);SportsEventAuthoring.Box("Perfect launch band",new Vector3(0,2.218f,-2),new Vector3(6.9f,.025f,1),gold);
  m.truck=SportsEventAuthoring.Truck(m,Folder,"Active dock diver",new Vector3(0,2.62f,-26),0);m.truck.gameObject.AddComponent<DockContact>().match=m;m.split=m.truck.gameObject.AddComponent<DockSplitVisual>();m.split.upper=m.truck.visuals.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name=="Cab"||r.name.ToLowerInvariant().Contains("glass")||r.bounds.center.y>m.truck.transform.position.y+.65f).Select(r=>r.transform).ToArray();
  m.staged=new SportsEventTruck[8];for(int i=0;i<8;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Staged competitor "+(i+1),new Vector3(-8-i%2*3,2.62f,-24+i/2*4),i);m.staged[i]=t;}
  m.replay=m.gameObject.AddComponent<DockReplay>();var ghost=new GameObject("Recorded replay truck · no colliders");m.replay.ghost=ghost.transform;var copy=UnityEngine.Object.Instantiate(m.truck.visuals.gameObject,ghost.transform,false);var original=m.truck.visuals.GetComponentsInChildren<MeshRenderer>();var replicas=copy.GetComponentsInChildren<MeshRenderer>();var upper=ghost.AddComponent<DockSplitVisual>();upper.upper=Enumerable.Range(0,original.Length).Where(i=>m.split.upper.Contains(original[i].transform)).Select(i=>replicas[i].transform).ToArray();m.replay.ghostSplit=upper;m.replay.live=m.truck.visuals.GetComponentsInChildren<Renderer>();ghost.SetActive(false);
  m.splash=new GameObject("Pooled pool splash").AddComponent<ParticleSystem>();var main=m.splash.main;main.playOnAwake=false;main.loop=false;main.duration=1.1f;main.startLifetime=.9f;main.startSpeed=7;main.startSize=.45f;main.startColor=new Color(.65f,.9f,1,.85f);main.gravityModifier=1.2f;main.maxParticles=130;var emission=m.splash.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,100)});var shape=m.splash.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=55;shape.radius=1;var particleMaterial=SportsEventAuthoring.Mat(Folder,"Splash spray",new Color(.7f,.94f,1,.9f));particleMaterial.shader=Shader.Find("Universal Render Pipeline/Particles/Unlit");m.splash.GetComponent<ParticleSystemRenderer>().sharedMaterial=particleMaterial;m.splash.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);
  m.bestMarker=SportsEventAuthoring.Box("Best distance ribbon",new Vector3(0,.04f,0),new Vector3(21,.04f,.12f),gold).transform;m.broadcast=SportsEventAuthoring.Camera("Dock television camera");m.cameras=new[]{m.broadcast.view};m.broadcast.Pose(new Vector3(0,2,-10),new Vector3(12,14,-24),58,true);DockPresentationAuthoring.Install(m);DockVenueDressing.Install(m);DockPoolEdgeAuthoring.Install();SportsEventAuthoring.UI(m);DockSlangAuthoring.Install(m);SportsEventAuthoring.Save(Folder);Validate();}
 public static void Validate(){var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<DockMatch>();if(m==null||m.truck.wheels.Length!=4||m.staged.Length!=8||m.replay.ghost.GetComponentsInChildren<Collider>(true).Length!=0||m.split.upper.Length==0||m.menus.names.Length!=8||m.waterVolume==null||m.feedback.clips.Any(c=>c==null))throw new System.Exception("Dock Diving saved references incomplete");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new System.Exception("Dock listener count");if(DockMatch.Inches(.3048f)!=12||DockMatch.Quality(.6f)!="PERFECT"||DockMatch.Quality(5)!="EARLY"||DockMatch.Quality(-1)!="LATE")throw new System.Exception("Dock precision/timing fixtures");SportsEventSourceFixtures.Run(m);Debug.Log("DOCK_SAVED_VALIDATED");}
}
}
